package com.stevesuzon.carlplay;

import android.Manifest;import android.annotation.SuppressLint;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.net.*;import android.net.Uri;import android.os.Bundle;import android.os.SystemClock;import android.provider.Settings;import android.view.*;import android.webkit.*;import android.widget.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.Locale;import java.net.HttpURLConnection;import java.net.URL;

public class MainActivity extends Activity{
 static final int LOCATION_REQUEST=1001;static final long DAY=86400000L,LICENSE_DAYS=365L,GRACE_DAYS=7L;static final String PREFS="carlplay_license",SECRET="CP66-365-RENOUVELLEMENT-SUZON-2026";
 WebView webView;ConnectivityManager cm;ConnectivityManager.NetworkCallback cb;SharedPreferences prefs;TextView badge;FrameLayout root;
 public class AndroidStatus{
  @JavascriptInterface public boolean hasInternet(){try{Network n=cm.getActiveNetwork();NetworkCapabilities c=n==null?null:cm.getNetworkCapabilities(n);return c!=null&&c.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)&&c.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED);}catch(Exception e){return false;}}
  @JavascriptInterface public boolean licenseExpired(){return expired(now());}
  @JavascriptInterface public String licenseRequestCode(){return formatReq(requestCode());}
  @JavascriptInterface public String renewLicense(String code){return renew(code)?"OK":"ERREUR";}
  @JavascriptInterface public long licenseDaysLeft(){return daysLeft(now());}
 }
 long trustedClock(){long epoch=prefs.getLong("trusted_epoch",0L),elapsed=prefs.getLong("trusted_elapsed",0L);if(epoch<=0||elapsed<=0)return 0L;long d=SystemClock.elapsedRealtime()-elapsed;return d>=0?epoch+d:epoch;}
 long now(){long system=System.currentTimeMillis(),trusted=trustedClock(),last=prefs.getLong("last_seen",0L);long e=Math.max(last,Math.max(system,trusted));prefs.edit().putLong("last_seen",e).apply();return e;}
 long start(){long s=prefs.getLong("license_start",0);if(s==0){long base=trustedClock();if(base<=0)base=System.currentTimeMillis();s=base;prefs.edit().putLong("license_start",s).putLong("last_seen",s).apply();}return s;}
 void syncInternetTime(){new Thread(()->{HttpURLConnection c=null;try{URL u=new URL("https://www.google.com/generate_204");c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setUseCaches(false);c.setRequestMethod("HEAD");c.connect();long server=c.getDate();if(server<=0){String d=c.getHeaderField("Date");if(d!=null)server=java.util.Date.parse(d);}if(server>1609459200000L){long elapsed=SystemClock.elapsedRealtime();long oldStart=prefs.getLong("license_start",0L);long sys=System.currentTimeMillis();SharedPreferences.Editor ed=prefs.edit().putLong("trusted_epoch",server).putLong("trusted_elapsed",elapsed).putLong("last_seen",Math.max(prefs.getLong("last_seen",0L),server));if(oldStart==0L||Math.abs(oldStart-server)>30L*DAY&&Math.abs(sys-server)>30L*DAY)ed.putLong("license_start",server);ed.apply();runOnUiThread(()->updateBadge());}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}}).start();}
 long daysLeft(long n){long e=start()+LICENSE_DAYS*DAY;return n>=e?0:(long)Math.ceil((e-n)/(double)DAY);}
 long graceLeft(long n){long e=start()+(LICENSE_DAYS+GRACE_DAYS)*DAY;return n>=e?0:(long)Math.ceil((e-n)/(double)DAY);}
 boolean expired(long n){return n>=start()+(LICENSE_DAYS+GRACE_DAYS)*DAY;}
 String hash(String v){try{MessageDigest m=MessageDigest.getInstance("SHA-256");byte[] b=m.digest(v.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.US,"%02x",x&255));return s.toString();}catch(Exception e){return"0000000000000000";}}
 String requestCode(){String id=Settings.Secure.getString(getContentResolver(),Settings.Secure.ANDROID_ID);if(id==null)id="unknown";int c=prefs.getInt("renewal_cycle",0);String h=hash(id+"|"+c+"|"+start());long n;try{n=Long.parseUnsignedLong(h.substring(0,12),16)%100000000L;}catch(Exception e){n=0;}return String.format(Locale.US,"%08d",n);}
 String formatReq(String s){return s.substring(0,2)+"."+s.substring(2,4)+"."+s.substring(4,6)+"."+s.substring(6,8);}
 String expected(){String h=hash(SECRET+"|"+requestCode());long n;try{n=Long.parseUnsignedLong(h.substring(0,12),16)%100000000L;}catch(Exception e){n=0;}return String.format(Locale.US,"%08d",n);}
 boolean renew(String entered){String x=entered==null?"":entered.replaceAll("[^0-9]","");if(!expected().equals(x))return false;int c=prefs.getInt("renewal_cycle",0)+1;long n=now();prefs.edit().putLong("license_start",n).putLong("last_seen",n).putInt("renewal_cycle",c).apply();runOnUiThread(()->{updateBadge();Toast.makeText(this,"Abonnement renouvelé pour 365 jours",Toast.LENGTH_LONG).show();});return true;}
 void updateBadge(){if(badge==null)return;long n=now(),d=daysLeft(n);if(d>0){badge.setText("LICENCE  •  "+d+" JOURS RESTANTS");badge.setBackgroundColor(Color.argb(210,5,72,120));}else if(!expired(n)){long g=graceLeft(n);badge.setText("GRÂCE  •  "+g+" JOURS  •  CONTACTEZ POUR RENOUVELER");badge.setBackgroundColor(Color.argb(225,170,95,0));}else{badge.setText("ABONNEMENT EXPIRÉ");badge.setBackgroundColor(Color.argb(235,150,20,20));}webView.setVisibility(View.VISIBLE);}
 void makeBadge(){badge=new TextView(this);badge.setTextColor(Color.WHITE);badge.setTextSize(15);badge.setTypeface(Typeface.DEFAULT_BOLD);badge.setGravity(Gravity.CENTER_VERTICAL);int h=(int)(12*getResources().getDisplayMetrics().density),v=(int)(7*getResources().getDisplayMetrics().density);badge.setPadding(h,v,h,v);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.LEFT);int m=(int)(8*getResources().getDisplayMetrics().density);p.setMargins(m,m,m,m);root.addView(badge,p);}
 void notifyNet(){if(webView!=null)webView.post(()->webView.evaluateJavascript("if(window.updateNetworkStatus)window.updateNetworkStatus();",null));}
 void injectUi(WebView v){v.evaluateJavascript("(function(){var s=document.createElement('script');s.src='license-ui.js?'+Date.now();document.head.appendChild(s)})()",null);}
 @SuppressLint({"SetJavaScriptEnabled","AllowFileAccessFromFileURLs"}) public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894);prefs=getSharedPreferences(PREFS,MODE_PRIVATE);start();cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);root=new FrameLayout(this);webView=new WebView(this);root.addView(webView,new FrameLayout.LayoutParams(-1,-1));makeBadge();setContentView(root);WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setGeolocationEnabled(true);s.setUseWideViewPort(true);s.setLoadWithOverviewMode(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setAllowFileAccessFromFileURLs(true);s.setAllowUniversalAccessFromFileURLs(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_ALWAYS_ALLOW);webView.addJavascriptInterface(new AndroidStatus(),"AndroidStatus");webView.setWebChromeClient(new WebChromeClient(){public void onGeolocationPermissionsShowPrompt(String o,GeolocationPermissions.Callback c){c.invoke(o,true,false);}});webView.setWebViewClient(new WebViewClient(){boolean h(String u){if(u==null||u.startsWith("file:")||u.startsWith("about:"))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){}return true;}public boolean shouldOverrideUrlLoading(WebView v,String u){return h(u);}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return h(r.getUrl().toString());}public void onPageFinished(WebView v,String u){super.onPageFinished(v,u);injectUi(v);}});if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOCATION_REQUEST);cb=new ConnectivityManager.NetworkCallback(){public void onAvailable(Network n){notifyNet();syncInternetTime();}public void onLost(Network n){notifyNet();}public void onCapabilitiesChanged(Network n,NetworkCapabilities c){notifyNet();if(c.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED))syncInternetTime();}};try{cm.registerDefaultNetworkCallback(cb);}catch(Exception e){}webView.loadUrl("file:///android_asset/index.html");updateBadge();if(new AndroidStatus().hasInternet())syncInternetTime();}
 protected void onResume(){super.onResume();updateBadge();if(new AndroidStatus().hasInternet())syncInternetTime();}protected void onDestroy(){try{cm.unregisterNetworkCallback(cb);}catch(Exception e){}super.onDestroy();}public void onBackPressed(){if(webView.canGoBack())webView.goBack();else super.onBackPressed();}
}
